<template>
  <div class="http-api">
    <!-- 重命名弹窗 -->
    <div class="edit-modal-mask" v-if="isEditing" @click.self="closeEdit">
      <div class="edit-modal">
        <div class="edit-modal-title">重命名接口</div>
        <input
          type="text"
          class="edit-modal-input"
          v-model="editName"
          placeholder="请输入名称"
          @keydown.enter.exact.prevent="submitEdit"
        />
        <div class="edit-modal-footer">
          <button @click="closeEdit" class="btn btn-ghost">取消</button>
          <button @click="submitEdit" class="btn btn-primary">确认</button>
        </div>
      </div>
    </div>

    <!-- API 标签栏 -->
    <div class="api-tabs-bar">
      <div class="api-tabs-scroll">
        <VueDraggable
          class="api-tabs"
          v-model="apilist"
          @update="draggableEnd"
        >
          <div
            class="api-tab"
            :class="{ active: chosenId === item.id }"
            v-for="item in apilist"
            :key="item.id"
          >
            <el-tooltip
              effect="light"
              :content="item.name"
              placement="bottom"
              :open-delay="400"
            >
              <span
                class="api-tab-name"
                @dblclick="editApi(item)"
                @click="selectApi(item)"
                @contextmenu.prevent="itemContextMenu(item)"
                >{{ item.name }}</span
              >
            </el-tooltip>
            <span class="api-tab-close" @click.stop="removeApi(item)">×</span>
          </div>
        </VueDraggable>
      </div>
      <button class="api-add-btn" title="新建接口" @click="addApi">
        <i class="el-icon-plus"></i>
      </button>
    </div>

    <!-- 本地代理条：下载 + 注册/启动 -->
    <div class="agent-bar">
      <i class="el-icon-connection"></i>
      <span class="agent-tip">请求由本地代理转发，可绕过浏览器跨域限制</span>
      <span class="agent-actions">
        <a class="agent-btn" :href="agentExeUrl" download="api.exe">
          <i class="el-icon-download"></i>下载代理程序
        </a>
        <button class="agent-btn" @click="registerAgent">
          <i class="el-icon-position"></i>启动/注册代理
        </button>
      </span>
    </div>

    <!-- 顶部工具栏 -->
    <div class="toolbar">
      <select
        v-model="request.method"
        class="method-select"
        :class="'method-' + request.method.toLowerCase()"
      >
        <option>GET</option>
        <option>POST</option>
        <option>PUT</option>
        <option>DELETE</option>
        <option>PATCH</option>
        <option>HEAD</option>
        <option>OPTIONS</option>
      </select>
      <input
        type="text"
        v-model.trim="request.url"
        class="url-input url-input-default"
        id="url-input"
        placeholder="请输入请求地址，如 https://api.example.com/upload"
        @keydown.enter.exact.prevent="sendRequest"
      />
      <button
        class="send-btn"
        @click="sendRequest"
        :disabled="response.loading"
      >
        <i class="el-icon-position"></i>
        {{ response.loading ? "发送中…" : "发送" }}
      </button>
    </div>

    <!-- 主区域: 请求 / 响应 -->
    <div class="main-panel">
      <!-- 左侧请求配置 -->
      <div class="request-panel">
        <div class="panel-head">
          <span class="panel-title">请求</span>
          <div class="section-tabs">
            <div
              class="tab"
              :class="{ active: requestTab === 'headers' }"
              @click="changeRequestTab('headers')"
            >
              Headers
            </div>
            <div
              class="tab"
              :class="{ active: requestTab === 'body' }"
              @click="changeRequestTab('body')"
            >
              Body
            </div>
          </div>
        </div>

        <!-- Headers 选项卡 -->
        <div class="tab-content" v-if="requestTab === 'headers'">
          <table class="key-value-table">
            <thead>
              <tr>
                <th style="width: 45%">Key</th>
                <th style="width: 45%">Value</th>
                <th style="width: 10%"></th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="(h, idx) in request.headers" :key="'h' + idx">
                <td><input v-model="h.key" placeholder="Header" /></td>
                <td><input v-model="h.value" placeholder="Value" /></td>
                <td class="row-op">
                  <button class="remove-btn" @click="removeHeader(idx)">
                    ✕
                  </button>
                </td>
              </tr>
            </tbody>
          </table>
          <button class="add-row-btn" @click="addHeader">
            <i class="el-icon-plus"></i> 添加请求头
          </button>
        </div>

        <!-- Body 选项卡 -->
        <div class="tab-content" v-if="requestTab === 'body'">
          <div class="body-options">
            <label
              class="body-radio"
              :class="{ on: request.bodyType === 'none' }"
            >
              <input
                type="radio"
                value="none"
                v-model="request.bodyType"
                @click="bodyChosen('none')"
              />
              none
            </label>
            <label
              class="body-radio"
              :class="{ on: request.bodyType === 'raw' }"
            >
              <input
                type="radio"
                value="raw"
                v-model="request.bodyType"
                @click="bodyChosen('raw')"
              />
              raw (JSON)
            </label>
            <label
              class="body-radio"
              :class="{ on: request.bodyType === 'urlencoded' }"
            >
              <input
                type="radio"
                value="urlencoded"
                v-model="request.bodyType"
                @click="bodyChosen('urlencoded')"
              />
              x-www-form-urlencoded
            </label>
            <label
              class="body-radio"
              :class="{ on: request.bodyType === 'form-data' }"
            >
              <input
                type="radio"
                value="form-data"
                v-model="request.bodyType"
                @click="bodyChosen('form-data')"
              />
              form-data
            </label>
            <button
              v-if="request.bodyType === 'raw'"
              class="beautify-btn"
              title="美化 JSON"
              @click="beautifyRaw"
            >
              <i class="el-icon-magic-stick"></i> Beautify
            </button>
          </div>

          <!-- raw JSON 输入框 -->
          <textarea
            v-if="request.bodyType === 'raw'"
            v-model="request.rawBody"
            class="body-raw-textarea"
            placeholder='{"key": "value"}'
            @contextmenu.prevent="bodyCopyMenu"
            spellcheck="false"
          ></textarea>

          <!-- urlencoded 键值对表格 -->
          <div v-if="request.bodyType === 'urlencoded'" class="body-table-wrap">
            <table class="key-value-table">
              <tbody>
                <tr
                  v-for="(p, idx) in request.urlencodedParams"
                  :key="'p' + idx"
                >
                  <td style="width: 45%">
                    <input v-model="p.key" placeholder="param" />
                  </td>
                  <td style="width: 45%">
                    <input v-model="p.value" placeholder="value" />
                  </td>
                  <td class="row-op">
                    <button class="remove-btn" @click="removeParam(idx)">
                      ✕
                    </button>
                  </td>
                </tr>
              </tbody>
            </table>
            <button class="add-row-btn" @click="addParam">
              <i class="el-icon-plus"></i> 添加参数
            </button>
          </div>

          <!-- form-data 键值/文件表格 -->
          <div v-if="request.bodyType === 'form-data'" class="body-table-wrap">
            <table class="key-value-table">
              <thead>
                <tr>
                  <th style="width: 28%">Key</th>
                  <th style="width: 48%">Value / 文件</th>
                  <th style="width: 14%">类型</th>
                  <th style="width: 10%"></th>
                </tr>
              </thead>
              <tbody>
                <tr
                  v-for="(p, idx) in request.formDataParams"
                  :key="'f' + idx"
                >
                  <td>
                    <input v-model="p.key" placeholder="字段名" />
                  </td>
                  <td>
                    <input
                      v-if="p.type === 'text'"
                      v-model="p.value"
                      placeholder="value"
                    />
                    <div v-else class="file-cell">
                      <span
                        class="file-name"
                        :class="{ empty: !p.name }"
                        :title="p.name"
                        >{{ p.name || "未选择文件" }}</span
                      >
                      <button class="file-pick-btn" @click="pickFile(idx)">
                        <i class="el-icon-folder-opened"></i> 选择
                      </button>
                    </div>
                  </td>
                  <td>
                    <select v-model="p.type" class="type-select">
                      <option value="text">Text</option>
                      <option value="file">File</option>
                    </select>
                  </td>
                  <td class="row-op">
                    <button class="remove-btn" @click="removeFormRow(idx)">
                      ✕
                    </button>
                  </td>
                </tr>
              </tbody>
            </table>
            <button class="add-row-btn" @click="addFormRow">
              <i class="el-icon-plus"></i> 添加参数
            </button>
            <!-- 隐藏的文件选择器（选择后以 base64 读取内容，随请求发给本地代理） -->
            <input
              type="file"
              ref="filePicker"
              style="display: none"
              @change="onFilePicked"
            />
          </div>

          <div v-if="request.bodyType === 'none'" class="body-none">
            无请求体
          </div>
        </div>
      </div>

      <!-- 右侧响应展示 -->
      <div class="response-panel">
        <div class="panel-head">
          <span class="panel-title">响应</span>
          <div class="section-tabs">
            <div
              class="tab"
              :class="{ active: responseTab === 'body' }"
              @click="responseTab = 'body'"
            >
              Body
            </div>
            <div
              class="tab"
              :class="{ active: responseTab === 'headers' }"
              @click="responseTab = 'headers'"
            >
              Headers
            </div>
          </div>
        </div>

        <div class="response-status">
          <span class="status-label">状态</span>
          <span
            v-if="response.status"
            class="status-badge"
            :class="statusClass"
          >
            {{ response.status }} {{ response.statusText }}
          </span>
          <span v-else class="status-badge idle">—</span>
          <span v-if="response.time" class="meta-info">
            <i class="el-icon-timer"></i> {{ response.time }} ms
          </span>
          <span v-if="response.loading" class="meta-info loading-dots"
            >请求中</span
          >
        </div>

        <!-- 响应头 -->
        <div class="response-headers" v-if="responseTab === 'headers'">
          <template v-if="hasResponseHeaders">
            <div
              v-for="(val, key) in response.headers"
              :key="key"
              class="header-item"
            >
              <span class="header-key">{{ key }}</span>
              <span class="header-value">{{ val }}</span>
            </div>
          </template>
          <div v-else class="placeholder small">无响应头</div>
        </div>

        <!-- 响应体 -->
        <div class="response-body" v-if="responseTab === 'body'">
          <button
            v-if="response.body"
            class="resp-copy-btn"
            title="复制响应体内容"
            @click="copyText(response.body)"
          >
            <i class="el-icon-document-copy"></i> 复制
          </button>
          <div v-if="response.error" class="error-message">
            <i class="el-icon-warning-outline"></i> 请求失败:
            {{ response.error }}
          </div>
          <pre
            v-else-if="response.body"
            class="language-json"
            @contextmenu.prevent="bodyCopyMenu"
            >{{ response.body }}</pre
          >
          <div v-else-if="response.loading" class="placeholder">等待响应…</div>
          <div v-else-if="!response.status" class="placeholder">
            点击「发送」开始测试
          </div>
          <div v-else class="placeholder">响应体为空</div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { VueDraggable } from "vue-draggable-plus";

// 本地代理（python/main.py 编译的 exe）：协议名/端口需与代理端保持一致
const AGENT_BASE = "http://127.0.0.1:17393";
const PROTOCOL_SCHEME = "archer-httpapi://";
const LIST_KEY = "httpapi-list";
const CHOSEN_KEY = "httpapi-chosen-id";
const POLL_INTERVAL = 1000;
const POLL_TIMEOUT = 30000;

/** UTF-8 安全的 base64 文本编解码 */
function b64encodeText(str) {
  return btoa(unescape(encodeURIComponent(str)));
}
function b64decodeText(b64) {
  try {
    return decodeURIComponent(escape(atob(b64)));
  } catch (e) {
    return atob(b64);
  }
}
/** payload -> urlsafe base64（供注册表协议 URL 携带） */
function b64urlEncode(obj) {
  return b64encodeText(JSON.stringify(obj))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

export default {
  name: "HttpApi",
  components: {
    VueDraggable,
  },
  data() {
    let chosenId = window.localStorage.getItem(CHOSEN_KEY) || "";
    return {
      agentExeUrl: process.env.BASE_URL + "reg/api.exe", // 本地代理下载地址（public/reg/api.exe）
      requestTab: "headers", // 'headers' 或 'body'
      responseTab: "body",
      chosenId: chosenId,
      isEditing: false,
      editName: "",
      apilist: [],
      request: {
        id: "",
        requestTab: "headers", // 'headers' 或 'body'
        sort: 0,
        name: "",
        method: "GET",
        url: "",
        headers: [{ key: "", value: "" }],
        bodyType: "none", // 'none', 'raw', 'urlencoded', 'form-data'
        rawBody: "",
        urlencodedParams: [{ key: "", value: "" }],
        formDataParams: [{ key: "", value: "", type: "text", path: "", name: "" }],
      },
      resList: [],
      response: {
        loading: false,
        status: null,
        statusText: "",
        headers: {},
        body: null,
        error: null,
        time: null,
      },
    };
  },
  computed: {
    hasResponseHeaders() {
      return (
        this.response.headers &&
        Object.keys(this.response.headers).length > 0
      );
    },
    /** 响应状态码颜色分级：2xx 绿 / 3xx 蓝 / 4xx 橙 / 5xx 红 */
    statusClass() {
      const s = this.response.status;
      if (!s) {
        return "";
      }
      if (s < 300) {
        return "s2";
      }
      if (s < 400) {
        return "s3";
      }
      if (s < 500) {
        return "s4";
      }
      return "s5";
    },
  },
  created() {
    this.loadApiList();
  },
  beforeDestroy() {
    clearTimeout(this._pollTimer);
  },
  methods: {
    /** 从 localStorage 加载接口列表（原 Electron 版由主进程持久化） */
    loadApiList() {
      let apilist = [];
      try {
        apilist = JSON.parse(window.localStorage.getItem(LIST_KEY)) || [];
      } catch (e) {
        apilist = [];
      }
      apilist.sort((a, b) => a.sort - b.sort);
      this.apilist = apilist;
      this.resList = [];
      for (let i = 0; i < this.apilist.length; i++) {
        this.resList.push(this.defaultResponse(this.apilist[i].id));
      }
      if (this.apilist.length <= 0) {
        this.request = this.defaultRequest();
        this.apilist.push(this.request);
        this.rememberChosen(this.request.id);
        this.resList.push(this.defaultResponse(this.request.id));
      } else {
        this.restoreChosenApi();
      }
      if (!this.request.requestTab) {
        this.request.requestTab = "headers";
      }
      this.ensureFormRows(this.request);
      this.requestTab = this.request.requestTab;
      this.refreshResponse();
    },
    /** 持久化接口列表到 localStorage；文件内容（base64）不落盘，仅保留文件名 */
    saveApiList() {
      const list = this.apilist.map((it) => ({
        ...it,
        formDataParams: (it.formDataParams || []).map((p) => ({
          key: p.key,
          value: p.value,
          type: p.type,
          name: p.name || "",
        })),
      }));
      try {
        window.localStorage.setItem(LIST_KEY, JSON.stringify(list));
      } catch (e) {}
    },
    /** 记忆当前选中标签 */
    rememberChosen(id) {
      this.chosenId = id;
      window.localStorage.setItem(CHOSEN_KEY, id);
    },
    /** 恢复选中标签：优先已记忆的 id，失效或缺失时回退到第一个标签并回写记忆 */
    restoreChosenApi() {
      let target = null;
      if (this.chosenId) {
        target =
          this.apilist.find((it) => String(it.id) === String(this.chosenId)) ||
          null;
      }
      if (!target && this.apilist.length > 0) {
        target = this.apilist[0];
      }
      if (target) {
        this.request = target;
        this.rememberChosen(target.id);
      }
    },
    defaultFormRow() {
      return { key: "", value: "", type: "text", name: "" };
    },
    /** 兼容旧数据：缺少 formDataParams 字段时补齐 */
    ensureFormRows(req) {
      if (req && !Array.isArray(req.formDataParams)) {
        this.$set(req, "formDataParams", [this.defaultFormRow()]);
      }
    },
    defaultRequest() {
      return {
        id: Date.now() + Math.random().toString(36).substring(2),
        sort: 0,
        name: "新建",
        requestTab: "headers", // 'headers' 或 'body'
        method: "GET",
        url: "",
        headers: [{ key: "", value: "" }],
        bodyType: "none",
        rawBody: "",
        urlencodedParams: [{ key: "", value: "" }],
        formDataParams: [this.defaultFormRow()],
      };
    },
    defaultResponse(id) {
      return {
        id: id,
        loading: false,
        status: null,
        statusText: "",
        headers: {},
        body: null,
        error: null,
        time: null,
      };
    },
    editApi(item) {
      this.editName = item.name;
      this.isEditing = true;
      this.selectApi(item);
    },
    closeEdit() {
      this.editName = "";
      this.isEditing = false;
    },
    submitEdit() {
      this.request.name = this.editName;
      this.editName = "";
      this.isEditing = false;
      this.saveApiList();
    },
    itemContextMenu(item) {
      // 浏览器环境无原生右键菜单，右键标签直接进入重命名
      this.editApi(item);
    },
    draggableEnd(event) {
      for (let i = 0; i < this.apilist.length; i++) {
        this.apilist[i].sort = i + 1;
      }
      this.saveApiList();
    },
    refreshResponse(res) {
      if (this.resList.length !== this.apilist.length) {
        for (let i = 0; i < this.apilist.length; i++) {
          this.resList.push(this.defaultResponse(this.apilist[i].id));
        }
      }
      if (res) {
        for (let i = 0; i < this.resList.length; i++) {
          if (this.request.id === this.resList[i].id) {
            res.id = this.request.id;
            this.resList[i] = res;
            this.response = res;
            break;
          }
        }
      } else {
        for (let i = 0; i < this.resList.length; i++) {
          if (this.request.id === this.resList[i].id) {
            this.response = this.resList[i];
            break;
          }
        }
      }
    },
    selectApi(request) {
      this.request = request;
      this.ensureFormRows(this.request);
      this.requestTab = this.request.requestTab;
      this.refreshResponse();
      this.rememberChosen(this.request.id);
    },
    removeApi(item) {
      if (this.chosenId === item.id) {
        let idx = 0;
        for (; idx < this.apilist.length; idx++) {
          if (this.chosenId === this.apilist[idx].id) {
            break;
          }
        }
        this.apilist = this.apilist.filter((it) => {
          return it.id !== item.id;
        });
        this.resList = this.resList.filter((it) => {
          return it.id !== item.id;
        });
        if (this.apilist.length <= 0) {
          this.request = this.defaultRequest();
          this.apilist.push(this.request);
          this.rememberChosen(this.request.id);
          this.response = this.defaultResponse(this.request.id);
          this.resList.push(this.response);
        } else {
          if (idx === 0) {
            idx = idx + 1;
          } else {
            idx = idx - 1;
          }
          this.selectApi(this.apilist[idx]);
        }
      } else {
        this.apilist = this.apilist.filter((it) => {
          return it.id !== item.id;
        });
      }
      this.saveApiList();
    },
    addApi() {
      let sort = 1;
      if (this.apilist.length > 0) {
        sort = this.apilist[this.apilist.length - 1].sort + 1;
      }
      this.request = this.defaultRequest();
      this.requestTab = this.request.requestTab;
      this.rememberChosen(this.request.id);
      this.apilist.push(this.request);
      this.response = this.defaultResponse(this.request.id);
      this.resList.push(this.response);
      this.saveApiList();
    },
    changeRequestTab(tab) {
      this.request.requestTab = tab;
      this.requestTab = tab;
    },
    // 请求头管理
    addHeader() {
      this.request.headers.push({ key: "", value: "" });
    },
    removeHeader(index) {
      this.request.headers.splice(index, 1);
    },
    // urlencoded 参数管理
    addParam() {
      this.request.urlencodedParams.push({ key: "", value: "" });
    },
    removeParam(index) {
      this.request.urlencodedParams.splice(index, 1);
    },
    // form-data 参数管理
    addFormRow() {
      this.request.formDataParams.push(this.defaultFormRow());
    },
    removeFormRow(index) {
      this.request.formDataParams.splice(index, 1);
    },
    /** 触发隐藏的文件选择器，记录当前行号 */
    pickFile(idx) {
      this._fileRow = idx;
      const picker = this.$refs.filePicker;
      if (picker) {
        picker.value = "";
        picker.click();
      }
    },
    /** 文件选择完成：浏览器环境无 File.path，读取内容为 base64 随请求发给代理 */
    onFilePicked(e) {
      const file = e.target.files && e.target.files[0];
      if (!file) {
        return;
      }
      const row = this.request.formDataParams[this._fileRow];
      if (!row) {
        return;
      }
      const reader = new FileReader();
      reader.onload = () => {
        const dataUrl = String(reader.result || "");
        row.data = dataUrl.includes(",") ? dataUrl.split(",")[1] : dataUrl;
        row.name = file.name;
        if (!row.key.trim()) {
          row.key = "file";
        }
      };
      reader.readAsDataURL(file);
    },

    // 构建最终 headers 对象 (过滤空key)
    buildHeaders() {
      let headersObj = {};
      this.request.headers.forEach((h) => {
        let key = h.key.trim();
        if (key !== "") {
          headersObj[key] = h.value;
        }
      });
      return headersObj;
    },
    bodyCopyMenu() {
      // 浏览器环境无原生右键菜单：有选中文本时直接复制
      const text = window.getSelection().toString();
      if (text) {
        this.copyText(text);
      }
    },
    /** 美化 raw JSON 请求体 */
    beautifyRaw() {
      const raw = (this.request.rawBody || "").trim();
      if (!raw) {
        this.$message.warning("请求体为空");
        return;
      }
      try {
        this.request.rawBody = JSON.stringify(JSON.parse(raw), null, 2);
        this.$message.success("已美化");
      } catch (e) {
        this.$message.warning("JSON 格式错误，无法美化");
      }
    },
    copyText(text) {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard
          .writeText(text)
          .then(() => this.$message.success("已复制"))
          .catch(() => this.$message.warning("复制失败"));
      } else {
        const ta = document.createElement("textarea");
        ta.value = text;
        document.body.appendChild(ta);
        ta.select();
        try {
          document.execCommand("copy");
          this.$message.success("已复制");
        } catch (e) {
          this.$message.warning("复制失败");
        }
        document.body.removeChild(ta);
      }
    },

    bodyChosen(bodyType) {
      let headers = this.buildHeaders();
      let hasContentType = Object.keys(headers).some(
        (k) => k.toLowerCase() === "content-type"
      );
      if (bodyType === "raw") {
        this.request.headers = this.request.headers.filter((h) => {
          if (h.key.toLowerCase() === "content-type") {
            h.value = "application/json";
          }
          return h.key !== "";
        });
        if (!hasContentType) {
          this.request.headers.push({
            key: "Content-Type",
            value: "application/json",
          });
        }
      }

      if (bodyType === "none") {
        if (hasContentType) {
          this.request.headers = this.request.headers.filter((h) => {
            return h.key.toLowerCase() !== "content-type";
          });
        }
        if (this.request.headers.length <= 0) {
          this.request.headers.push({ key: "", value: "" });
        }
      }

      if (bodyType === "urlencoded") {
        this.request.headers = this.request.headers.filter((h) => {
          if (h.key.toLowerCase() === "content-type") {
            h.value = "application/x-www-form-urlencoded";
          }
          return h.key !== "";
        });
        if (!hasContentType) {
          this.request.headers.push({
            key: "Content-Type",
            value: "application/x-www-form-urlencoded",
          });
        }
      }

      // form-data 的 Content-Type（含 boundary）由主进程构造时自动覆盖，这里移除手动设置
      if (bodyType === "form-data") {
        this.request.headers = this.request.headers.filter((h) => {
          return h.key.toLowerCase() !== "content-type";
        });
        if (this.request.headers.length <= 0) {
          this.request.headers.push({ key: "", value: "" });
        }
      }
    },

    // 核心：发送请求
    async sendRequest() {
      this.saveApiList();

      let input = document.getElementById("url-input");
      input.setAttribute("class", "url-input url-input-default");
      input.setAttribute(
        "placeholder",
        "请输入请求地址，如 https://api.example.com/upload"
      );
      let url = this.request.url;
      if (!url) {
        input.setAttribute("class", "url-input url-input-change");
        this.$message.warning("请输入请求地址");
        return;
      }
      // 缺协议头时自动补全 https://（与 Postman 行为一致），并回填到输入框
      if (!url.startsWith("http://") && !url.startsWith("https://")) {
        url = "https://" + url;
        this.request.url = url;
      }

      // 构建发给本地代理的 payload（body 统一 base64 编码）
      const payload = this.buildPayload();
      if (!payload) {
        // 构建失败（如文件内容需重新选择），保持当前响应展示
        return;
      }

      // 重置响应状态，开启loading
      this.response = {
        loading: true,
        status: null,
        statusText: "",
        headers: {},
        body: null,
        error: null,
        time: null,
      };

      // 页面部署在 HTTPS（GitHub Pages）上，直连本地 HTTP 服务会被浏览器拦截，
      // 统一走注册表协议拉起本地代理，随后轮询取回结果
      this.launchAgentAndPoll(payload);
    },
    /** 构建请求 payload：{reqId, method, url, headers, body(base64), formData} */
    buildPayload() {
      let method = this.request.method.toUpperCase();
      let headers = this.buildHeaders();

      // GET/HEAD 不能有 body
      let canHaveBody = !["GET", "HEAD"].includes(method);
      let body = null;
      let formData = null;

      if (canHaveBody && this.request.bodyType !== "none") {
        if (this.request.bodyType === "raw") {
          body = b64encodeText(this.request.rawBody || "");
          let hasContentType = Object.keys(headers).some(
            (k) => k.toLowerCase() === "content-type"
          );
          if (!hasContentType) {
            headers["Content-Type"] = "application/json";
          }
        } else if (this.request.bodyType === "urlencoded") {
          let params = this.request.urlencodedParams.filter(
            (p) => p.key.trim() !== ""
          );
          if (params.length > 0) {
            let urlSearchParams = new URLSearchParams();
            params.forEach((p) => urlSearchParams.append(p.key, p.value));
            body = b64encodeText(urlSearchParams.toString());
            let hasContentType = Object.keys(headers).some(
              (k) => k.toLowerCase() === "content-type"
            );
            if (!hasContentType) {
              headers["Content-Type"] = "application/x-www-form-urlencoded";
            }
          }
        } else if (this.request.bodyType === "form-data") {
          // 拆分文本字段与文件字段，文件内容以 base64 随 payload 发给代理
          const fields = [];
          const files = [];
          for (const p of this.request.formDataParams) {
            if (p.key.trim() === "") {
              continue;
            }
            if (p.type === "file") {
              if (p.data) {
                files.push({ key: p.key, name: p.name || "blob", data: p.data });
              } else if (p.name) {
                this.$message.warning(
                  "文件「" + p.name + "」需要重新选择（浏览器无法持久化文件内容）"
                );
                return null;
              }
            } else {
              fields.push({ key: p.key, value: p.value });
            }
          }
          if (fields.length > 0 || files.length > 0) {
            formData = { fields, files };
          }
        }
      }

      headers = Object.fromEntries(
        Object.entries(headers).filter(([key]) => key && key.trim() !== "")
      );

      return {
        reqId: this.request.id + "-" + Date.now(),
        method,
        url: this.request.url,
        headers,
        body,
        formData,
      };
    },
    /** 代理响应 -> 页面响应展示（字段与 python/main.py execute_request 返回保持一致，JSON 自动美化） */
    applyAgentResponse(result) {
      let text = null;
      if (result.body) {
        text = b64decodeText(result.body);
        const headers = result.headers || {};
        const ctKey = Object.keys(headers).find(
          (k) => k.toLowerCase() === "content-type"
        );
        if (ctKey && /json/i.test(headers[ctKey])) {
          try {
            text = JSON.stringify(JSON.parse(text), null, 2);
          } catch (e) {}
        }
      }
      this.refreshResponse({
        loading: false,
        status: result.status || null,
        statusText: result.reason || "",
        headers: result.headers || {},
        body: text,
        error: result.error || null,
        time: result.time || null,
      });
    },
    /** 通过自定义协议拉起本地代理（exe 启动时会自动完成注册表注册/自愈） */
    registerAgent() {
      window.location.href = PROTOCOL_SCHEME;
      this.$message({
        type: "info",
        message:
          "请在浏览器弹窗中允许打开 api.exe；若无反应，请先下载并手动运行一次代理程序",
        duration: 5000,
      });
    },
    /** 代理离线：经注册表协议拉起 exe，并轮询本地服务取回结果 */
    launchAgentAndPoll(payload) {
      const encoded = b64urlEncode(payload);
      // 浏览器会弹出"打开应用"确认框
      window.location.href = PROTOCOL_SCHEME + encoded;
      this.$message({
        type: "info",
        message: "正在拉起本地代理…请在浏览器弹窗中允许打开 api.exe",
        duration: 4000,
      });

      const deadline = Date.now() + POLL_TIMEOUT;
      const poll = async () => {
        if (Date.now() > deadline) {
          this.applyAgentResponse({
            error:
              "本地代理未响应：请在浏览器弹窗中允许打开 api.exe（未安装请先点击上方「下载代理程序」运行后再试）",
          });
          return;
        }
        try {
          const r = await fetch(
            AGENT_BASE + "/response?id=" + encodeURIComponent(payload.reqId)
          );
          if (r.status === 200) {
            this.applyAgentResponse(await r.json());
            return;
          }
        } catch (e) {
          // 代理尚未启动完成，继续轮询
        }
        this._pollTimer = setTimeout(poll, POLL_INTERVAL);
      };
      this._pollTimer = setTimeout(poll, POLL_INTERVAL);
    },
  },
};
</script>

